6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":963,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 2.72\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T614,"])self.__next_f.push([1,"One can attain Kṛṣṇa consciousness or divine life at once, within a second – or one may not attain such a state of life even after millions of births. It is only a matter of understanding and accepting the fact. Khaṭvāṅga Mahārāja attained this state of life just a few minutes before his death, by surrendering unto Kṛṣṇa. Nirvāṇa means ending the process of materialistic life. According to Buddhist philosophy, there is only void after the completion of this material life, but Bhagavad-gītā teaches differently. Actual life begins after the completion of this material life. For the gross materialist it is sufficient to know that one has to end this materialistic way of life, but for persons who are spiritually advanced, there is another life after this materialistic life. Before ending this life, if one fortunately becomes Kṛṣṇa conscious, he at once attains the stage of brahma-nirvāṇa. There is no difference between the kingdom of God and the devotional service of the Lord. Since both of them are on the absolute plane, to be engaged in the transcendental loving service of the Lord is to have attained the spiritual kingdom. In the material world there are activities of sense gratification, whereas in the spiritual world there are activities of Kṛṣṇa consciousness. Attainment of Kṛṣṇa consciousness even during this life is immediate attainment of Brahman, and one who is situated in Kṛṣṇa consciousness has certainly already entered into the kingdom of God."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":963,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"72\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 72\",\"advanced_view_url_path\":\"/en/library/bg/2/advanced-view/#bb861\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/2/72/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/2/72/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/2/72/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/2/72/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/2/72/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"enabled\":t